-- Chunk 7/9 (50 outils)
BEGIN;

UPDATE tools SET long_description = E'Airtable, c''est la base de données flexible qui remplace 5 outils (CRM, projets, contenus). À partir de 20.78€/mois. Particulièrement pertinent pour les consultants B2B et les community-manager.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : vous gérez des données complexes (clients, projets, contenus) ou vous voulez remplacer Excel/Sheets par quelque chose de plus visuel. À éviter si : vous cherchez juste une todo-list simple (prenez Trello) ou vous détestez configurer des outils. Dès que vous jonglez entre Excel, Trello et un CRM et que vous voulez tout centraliser. Alternative gratuite à considérer : notion.', long_description_en = E'Airtable is the flexible database that replaces 5 tools (CRM, projects, content). Starting at €20.78/month. Most relevant for B2B consultants and community-manager.\n\nEstimated time saving: 4h/month with regular use.\n\nKeep it if: you manage complex data (customers, projects, content) or you want to replace Excel/Sheets with something more visual. Skip it if: you are just looking for a simple todo list (use Trello) or you hate configuring tools. As soon as you find yourself juggling Excel, Trello, and a CRM and want to centralize everything. Free alternative worth considering: notion.' WHERE slug = 'airtable';
UPDATE tools SET long_description = E'Slack, c''est la messagerie pro pour échanger avec clients et partenaires. À partir de 6.28€/mois. Particulièrement pertinent pour les manager-dsi et les fondateurs SaaS.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : vous collaborez avec des clients qui utilisent Slack ou vous gérez une petite équipe (2-5 personnes). À éviter si : vous êtes freelance 100% solo (les emails suffisent) ou vos clients n''utilisent pas Slack. Dès que vous collaborez régulièrement avec une équipe ou des clients qui utilisent Slack. Alternative gratuite à considérer : discord.', long_description_en = E'Slack is professional messaging for communicating with clients and partners. Starting at €6.28/month. Most relevant for manager-dsi and SaaS founders.\n\nEstimated time saving: 3h/month with regular use.\n\nKeep it if: you collaborate with clients who use Slack or you manage a small team (2-5 people). Skip it if: you are a 100% solo freelancer (emails are enough) or your clients do not use Slack. As soon as you collaborate regularly with a team or clients who use Slack. Free alternative worth considering: discord.' WHERE slug = 'slack';
UPDATE tools SET long_description = E'1Password, c''est le gestionnaire de mots de passe pro pour sécuriser tous vos comptes. À partir de 3.46€/mois. Particulièrement pertinent pour les manager-dsi et les developpeur-solo.\n\nGain de temps estimé : 1h/mois pour un usage régulier.\n\nÀ garder si : vous réutilisez les mêmes mots de passe partout (DANGER) ou vous gérez +20 comptes en ligne. À éviter si : vous avez moins de 10 comptes ou vous utilisez déjà Bitwarden (alternative gratuite). Dès que vous avez +15 comptes et que vous réutilisez des mots de passe. Alternative gratuite à considérer : bitwarden.', long_description_en = E'1Password is the professional password manager to secure all your accounts. Starting at €3.46/month. Most relevant for manager-dsi and solo developers.\n\nEstimated time saving: 1h/month with regular use.\n\nKeep it if: you reuse the same passwords everywhere (DANGER) or you manage +20 online accounts. Skip it if: you have fewer than 10 accounts or you already use Bitwarden (free alternative). As soon as you have more than 15 accounts and you are reusing passwords. Free alternative worth considering: bitwarden.' WHERE slug = '1password';
UPDATE tools SET long_description = E'Webflow, c''est créer des sites web pros sans coder, avec contrôle total du design. À partir de 12.12€/mois. Particulièrement pertinent pour les graphiste-da et les ux-ui.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : vous créez des sites pour clients ou vous voulez un contrôle total du design (exit WordPress). À éviter si : vous voulez juste une landing page simple (prenez Carrd) ou vous détestez apprendre de nouveaux outils. Dès que vous créez des sites web régulièrement et que WordPress vous limite. Alternative gratuite à considérer : carrd.', long_description_en = E'Webflow is create professional websites without coding, with complete design control. Starting at €12.12/month. Most relevant for graphiste-da and ux-ui.\n\nEstimated time saving: 5h/month with regular use.\n\nKeep it if: you build websites for clients or you want total design control (exit WordPress). Skip it if: you just want a simple landing page (get Carrd) or you hate learning new tools. As soon as you create websites regularly and WordPress starts to limit you. Free alternative worth considering: carrd.' WHERE slug = 'webflow';
UPDATE tools SET long_description = E'Pitch, c''est créer des présentations modernes et collaboratives pour impressionner les clients. À partir de 6.93€/mois. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : vous présentez régulièrement à des clients ou vous détestez PowerPoint et ses templates moches. À éviter si : vous faites moins de 2 présentations par an ou google Slides vous suffit. Dès que vous présentez régulièrement et que PowerPoint/Slides ne vous satisfont plus. Alternative gratuite à considérer : canva.', long_description_en = E'Pitch is create modern and collaborative presentations to impress clients. Starting at €6.93/month. Most relevant for B2B consultants and SaaS founders.\n\nEstimated time saving: 5h/month with regular use.\n\nKeep it if: you present to clients on a regular basis or you hate PowerPoint and its ugly templates. Skip it if: you create fewer than 2 presentations per year or google Slides is enough for you. As soon as you present regularly and PowerPoint/Slides no longer satisfy your needs. Free alternative worth considering: canva.' WHERE slug = 'pitch';
UPDATE tools SET long_description = E'Prezi, c''est présentations dynamiques avec zoom et animations. À partir de 4.33€/mois. Particulièrement pertinent pour les consultants B2B et les coach-formateur.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nDès que vous présentez régulièrement devant des clients et que l''effet visuel fait la différence. Alternative gratuite à considérer : canva.', long_description_en = E'Prezi is dynamic presentations with zoom and animations. Starting at €4.33/month. Most relevant for B2B consultants and coach-formateur.\n\nEstimated time saving: 5h/month with regular use.\n\nAs soon as you present to clients on a regular basis and the visual impact makes the difference. Free alternative worth considering: canva.' WHERE slug = 'prezi';
