UPDATE tools SET long_description = E'Ignition, c''est propositions commerciales et contrats professionnels. À partir de 59.76€/mois. Particulièrement pertinent pour les consultants B2B et les daf-finance.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : 5+ propositions commerciales par mois ou revenus 10k+$/mois. À éviter si : moins de 3 propositions/mois ou budget <69$/mois. Si vous envoyez 5+ propositions commerciales par mois. Alternative gratuite à considérer : indy.', long_description_en = E'Ignition is professional business proposals and contracts. Starting at €59.76/month. Most relevant for B2B consultants and daf-finance.\n\nEstimated time saving: 2h/month with regular use.\n\nKeep it if: 5+ sales proposals per month or revenue $10k+/month. Skip it if: less than 3 proposals/month or budget <$69/month. If you send 5+ sales proposals per month. Free alternative worth considering: indy.' WHERE slug = 'ignition';
UPDATE tools SET long_description = E'AdCreative.ai, c''est création publicitaire automatique avec IA. À partir de 18.19€/mois. Particulièrement pertinent pour les community-manager et les ecommercant.\n\nGain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : budget publicitaire 5000+$/mois ou besoin de tester 10+ créations/semaine. À éviter si : budget pub <1000$/mois ou campagnes occasionnelles. Si vous dépensez 1000+$/mois en publicité et testez 10+ créations/mois. Alternative gratuite à considérer : canva.', long_description_en = E'AdCreative.ai is automated ad creation with AI. Starting at €18.19/month. Most relevant for community-manager and ecommercant.\n\nEstimated time saving: 6h/month with regular use.\n\nKeep it if: advertising budget $5,000+/month or need to test 10+ creatives/week. Skip it if: ad budget <$1,000/month or occasional campaigns. If you spend $1,000+/month on advertising and test 10+ creatives/month. Free alternative worth considering: canva.' WHERE slug = 'adcreative';
